PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,phone TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('passenger','driver','admin')) DEFAULT 'passenger',driver_approved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS routes(id INTEGER PRIMARY KEY AUTOINCREMENT,from_name TEXT NOT NULL,to_name TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(from_name,to_name));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,passenger_id INTEGER NOT NULL REFERENCES users(id),driver_id INTEGER REFERENCES users(id),from_name TEXT NOT NULL,to_name TEXT NOT NULL,price INTEGER NOT NULL,passengers INTEGER NOT NULL DEFAULT 1 CHECK(passengers BETWEEN 1 AND 4),payment_method TEXT NOT NULL CHECK(payment_method IN ('cash','kaspi')),scheduled_at TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','in_progress','completed','cancelled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_orders_status_created ON orders(status,created_at);CREATE INDEX IF NOT EXISTS idx_orders_passenger ON orders(passenger_id,created_at);CREATE INDEX IF NOT EXISTS idx_orders_driver ON orders(driver_id,created_at);